import{_ as t,c as o,o as n,ah as s}from"./chunks/framework.RCw5T9E9.js";const p=JSON.parse('{"title":"Blacklist","description":"","frontmatter":{"title":"Blacklist"},"headers":[],"relativePath":"props/blacklist.md","filePath":"props/blacklist.md"}'),r={name:"props/blacklist.md"};function a(l,e,i,d,c,g){return n(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="component-blacklist-props" tabindex="-1">Component blacklist (Props) <a class="header-anchor" href="#component-blacklist-props" aria-label="Permalink to &quot;Component blacklist (Props)&quot;">​</a></h1><p>The <strong>Props</strong> <strong>blacklist</strong> is a set of <strong>Vue component names</strong> excluded from the inspector tree and table. Filtering runs <strong>before</strong> props collection, so hidden components are skipped during traversal.</p><p>Props overview: <a href="/qa-tools/docs/props/general.html">Overview</a>.</p><p>Do not confuse this with the <strong>site blacklist</strong> for overlay <strong>auto run</strong> (<strong>General / Auto Run</strong>): here only <strong>component names</strong> are filtered.</p><hr><h2 id="add-and-remove" tabindex="-1">Add and remove <a class="header-anchor" href="#add-and-remove" aria-label="Permalink to &quot;Add and remove&quot;">​</a></h2><ul><li><strong>Ignore by name</strong> in the row menu adds the current component name to <strong>Blocked</strong>. An empty name is ignored. A name already in <strong>Blocked</strong> or <strong>Allowed</strong> is not added again.</li><li><strong>Options → Props → Component Blacklist</strong> — the list and its details card are below.</li></ul><hr><h2 id="blocked-and-allowed" tabindex="-1">Blocked and Allowed <a class="header-anchor" href="#blocked-and-allowed" aria-label="Permalink to &quot;Blocked and Allowed&quot;">​</a></h2><p>Rules have two states:</p><ul><li><strong>Blocked</strong> — a matching name is hidden.</li><li><strong>Allowed</strong> — an exception. A name that matches any <strong>Allowed</strong> rule stays in the list even when a <strong>Blocked</strong> rule also matches.</li></ul><p><strong>Allowed</strong> rules do nothing when there is no <strong>Blocked</strong> rule. Deleting a row removes the rule entirely.</p><h3 id="component-blacklist-in-options" tabindex="-1">Component Blacklist in Options <a class="header-anchor" href="#component-blacklist-in-options" aria-label="Permalink to &quot;Component Blacklist in Options&quot;">​</a></h3><p>The block sits after <strong>Inspect Mode</strong>. The add field placeholder is <strong>Component name (supports wildcards: <em>Comp</em>)</strong>. <strong>Add</strong> or <strong>Enter</strong> trims the text and appends it to <strong>Blocked</strong>. An empty value shows <strong>Name cannot be empty</strong>. The same stored string already in <strong>Blocked</strong> or <strong>Allowed</strong> shows <strong>This name is already in the blacklist</strong>. That check is case-sensitive, so <code>Foo</code> and <code>foo</code> are two rules; name matching itself ignores case.</p><table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Component Name</strong></td><td>The stored pattern.</td></tr><tr><td><strong>Status</strong></td><td><strong>Blocked</strong> or <strong>Allowed</strong>. <strong>Allowed</strong> rows are dimmed.</td></tr></tbody></table><p><strong>Blocked</strong> rows come first, then <strong>Allowed</strong>, each in the order they were added. The row menu (right click or <strong>⋮</strong>) is <strong>Allow</strong> or <strong>Block</strong>, and <strong>Delete</strong>. The empty table says <em>No components in blacklist</em>.</p><p>A click opens <strong>Blacklist Details</strong>: <strong>Component Name</strong> and <strong>Status</strong> (<strong>Blocked</strong> or <strong>Allowed</strong>). There is no <strong>Edit</strong>. <strong>Back</strong> or <strong>Escape</strong> closes the card. With nothing selected the panel says <em>Select an item to see details</em>. If the rule was removed while the card is open, it says <em>Item no longer exists</em>. Below <strong>1000</strong> px the card covers the settings list until you go back.</p><p>The card does not select that component on the Props tab.</p><hr><h2 id="name-matching" tabindex="-1">Name matching <a class="header-anchor" href="#name-matching" aria-label="Permalink to &quot;Name matching&quot;">​</a></h2><p>Comparison uses the <strong>displayed component name</strong>.</p><ul><li>Without <strong><code>*</code></strong> or <strong><code>%</code></strong> — <strong>case-insensitive exact</strong> match.</li><li><strong><code>*</code></strong> and <strong><code>%</code></strong> act as wildcards for name fragments.</li></ul><p>Examples:</p><ul><li><code>MyButton</code> — only <strong>MyButton</strong>;</li><li><code>Base*</code> — names starting with <strong>Base</strong>;</li><li><code>*Modal*</code> — names containing <strong>Modal</strong>.</li></ul><p>Nameless components may show as <strong>Anonymous</strong> when that is what the tree uses.</p><hr><h2 id="intersections" tabindex="-1">Intersections <a class="header-anchor" href="#intersections" aria-label="Permalink to &quot;Intersections&quot;">​</a></h2><p>Any <strong>Allowed</strong> match wins: the name stays visible. Otherwise any <strong>Blocked</strong> match hides it.</p><p>A broad <strong>Blocked</strong> pattern plus a narrower <strong>Allowed</strong> pattern keeps the exception visible. Toggling the broad rule to <strong>Allowed</strong> turns that pattern into an exception for every name it matches.</p><hr><h2 id="when-it-applies" tabindex="-1">When it applies <a class="header-anchor" href="#when-it-applies" aria-label="Permalink to &quot;When it applies&quot;">​</a></h2><p>Rules run on every tree rebuild:</p><ul><li>manual <strong>Refresh</strong>;</li><li>automatic refresh;</li><li>reopening the tab.</li></ul><p>When the Props table already has rows, an <strong>Options</strong> edit refreshes it. An empty list picks up the rules on the next rebuild.</p><p>While a <strong>Blocked</strong> rule hides a name, that component is not selectable in the table or card.</p><hr><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Start from <strong>exact names</strong> via the row context menu.</li><li><strong>Wide patterns</strong> help repeated noise components but need care.</li><li><strong>Blacklist affects inspector display only</strong> — it does not change your Vue app.</li></ul><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/qa-tools/docs/props/general.html">Props overview</a></li><li><a href="/qa-tools/docs/props/inspect.html">Inspect</a></li><li><a href="/qa-tools/docs/options/customize.html">Customize</a></li></ul>',41)])])}const m=t(r,[["render",a]]);export{p as __pageData,m as default};
